LL ways;
int P, K;
int Parent[SIZE], Rank[SIZE];
set<int> groups;



int find_parent(int nd)
{
    if(Parent[nd] != nd)
        Parent[nd] = find_parent(Parent[nd]);

    return Parent[nd];
}


void Union(int nd1, int nd2)
{
    if(Rank[nd1] >= Rank[nd2])
    {
        Parent[nd2] = nd1;
        ++Rank[nd1];
    }

    else
    {
        Parent[nd1] = nd2;
        ++Rank[nd2];
    }
}




